@using sv_9740b91347f040bc9ec61b4aa8c2e6e8.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <!-- Left Sidebar -->
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Categories</h4>
            @if (_categories is not null)
            {
                @foreach (var category in _categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@(_selectedCategories.Contains(category))"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            }
            else
            {
                <p class="loading-text">Loading categories…</p>
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <div class="price-inputs">
                <input type="number" placeholder="Min" step="0.01" min="0"
                       @bind="_minPrice" @bind:event="onchange" />
                <span>–</span>
                <input type="number" placeholder="Max" step="0.01" min="0"
                       @bind="_maxPrice" @bind:event="onchange" />
            </div>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="_inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content -->
    <main class="catalog-main">
        <!-- Toolbar -->
        <div class="catalog-toolbar">
            <div class="sort-control">
                <label for="sort-select">Sort by:</label>
                <select id="sort-select" @bind="_sortBy" @bind:after="OnSortChanged">
                    <option value="price_asc">Price: Low to High</option>
                    <option value="price_desc">Price: High to Low</option>
                    <option value="name_asc">Name: A–Z</option>
                    <option value="rating_desc">Rating: Highest</option>
                </select>
            </div>
            @if (_result is not null)
            {
                <span class="results-summary">
                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount))
                    of @_result.TotalCount products
                </span>
            }
        </div>

        <!-- States -->
        @if (_loading)
        {
            <div class="catalog-status">
                <p>Loading products…</p>
            </div>
        }
        else if (_error is not null)
        {
            <div class="catalog-status catalog-error">
                <p>Error loading products: @_error</p>
                <button class="btn btn-primary" @onclick="() => LoadProductsAsync()">Retry</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-status">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <!-- Product Grid -->
            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <div class="product-card" @onclick="() => OnProductSelected(product)">
                        <div class="product-image" title="@product.Name">
                            @if (!string.IsNullOrWhiteSpace(product.ImageUrl))
                            {
                                <img src="@product.ImageUrl" alt="@product.Name" />
                            }
                            else
                            {
                                <div class="image-placeholder">
                                    <span>@product.Name</span>
                                </div>
                            }
                        </div>
                        <div class="product-info">
                            <h5 class="product-name">@product.Name</h5>
                            <p class="product-price">@product.Price.ToString("C")</p>
                            <p class="product-rating">@GetStarRating(product.Rating)</p>
                            @if (!product.InStock)
                            {
                                <span class="badge-out-of-stock">Out of Stock</span>
                            }
                            <button class="btn btn-cart"
                                    disabled="@(!product.InStock)"
                                    @onclick="() => AddToCart(product)"
                                    @onclick:stopPropagation="true">
                                Add to Cart
                            </button>
                        </div>
                    </div>
                }
            </div>

            <!-- Pagination -->
            <nav class="pagination">
                <button class="btn btn-page"
                        disabled="@(_currentPage <= 1)"
                        @onclick="() => GoToPage(_currentPage - 1)">
                    Previous
                </button>

                @for (int i = 1; i <= TotalPages; i++)
                {
                    var page = i;
                    <button class="btn btn-page @(page == _currentPage ? "active" : "")"
                            @onclick="() => GoToPage(page)">
                        @page
                    </button>
                }

                <button class="btn btn-page"
                        disabled="@(_currentPage >= TotalPages)"
                        @onclick="() => GoToPage(_currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

