                    <option value="name_asc">Name: A–Z</option>
                    <option value="rating_desc">Rating: Highest</option>
                </select>
            </div>
            @if (_result is not null)
            {
                <span class="results-summary">
                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount))
                    of @_result.TotalCount products
                </span>
            }
        </div>

        <!-- States -->
        @if (_loading)
        {
            <div class="catalog-status">
                <p>Loading products…</p>
            </div>
        }
        else if (_error is not null)
        {
            <div class="catalog-status catalog-error">
                <p>Error loading products: @_error</p>
                <button class="btn btn-primary" @onclick="() => LoadProductsAsync()">Retry</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-status">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <!-- Product Grid -->
            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <div class="product-card" @onclick="() => OnProductSelected(product)">
                        <div class="product-image" title="@product.Name">
                            @if (!string.IsNullOrWhiteSpace(product.ImageUrl))
                            {
                                <img src="@product.ImageUrl" alt="@product.Name" />
                            }
                            else
                            {
                                <div class="image-placeholder">
                                    <span>@product.Name</span>
                                </div>
                            }
                        </div>
                        <div class="product-info">
                            <h5 class="product-name">@product.Name</h5>
